cd /tmp && sed -i '' '$d' bot-check.mjs && cat >> bot-check.mjs <<'EOF'
assert.equal(r(m({}, { timeZone: "America/Los_Angeles" }), d("2026-10-22T18:00:00Z")), null); // 11:00
assert.equal(r(m({}, { timeZone: "America/New_York" }), d("2026-10-23T01:00:00Z")), "quiet_hours"); // 21:00 NY
assert.equal(r(m({}, { timeZone: "Pacific/Honolulu" }), d("2026-10-22T18:00:00Z")), null); // 08:00 HST
const noon = d("2026-10-22T18:00:00Z"), night = d("2026-10-23T05:00:00Z");
// transactional ignores hours, consent, opt-out
assert.equal(r(x({}, { marketingConsent: false, optedOutAt: "2026-01-01T00:00:00Z" }), night), null);
// marketing rules
assert.equal(r(m({}, { optedOutAt: "2026-01-01T00:00:00Z" }), noon), "opted_out");
assert.equal(r(m({}, { marketingConsent: false }), noon), "no_marketing_consent");
assert.equal(r(m({}, { marketingConsent: undefined }), noon), "no_marketing_consent");
assert.equal(r(m({ body: "Sale today!" }), noon), "missing_opt_out_notice");
assert.equal(r(m({}, { timeZone: "Mars/Base" }), noon), "invalid_time_zone");
assert.equal(r(m({}, { timeZone: undefined }), noon), "invalid_time_zone");
// opted out beats quiet hours; shared validation
assert.equal(r(m({}, { optedOutAt: "2026-01-01T00:00:00Z" }), night), "opted_out");
assert.equal(r(m({}, { phone: "+442071234567" }), noon), "invalid_phone");
assert.equal(r(x({}, { phone: "3125550142" }), noon), "invalid_phone");
assert.equal(r(x({ kind: "promo" }), noon), "unknown_kind");
assert.equal(r(x({ body: "  " }), noon), "empty_body");
assert.equal(r(null, noon), "invalid_message");
assert.throws(() => checkSms(m(), new Date("x")), TypeError);
// server TZ independence
console.log("ok");
EOF
for tz in UTC Asia/Tokyo America/Los_Angeles; do TZ=$tz node bot-check.mjs; done
